import {company,clients,sales,missions,guides} from './data.js';
import {evaluate,validateBackup,money} from './engine.js';
const $=s=>document.querySelector(s), KEY='rm-aljarafe-conecta-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={app:'aljarafe-conecta',version:1,name:'',work:{}};
try{const raw=localStorage.getItem(KEY);if(raw)state=validateBackup(JSON.parse(raw));}catch{ /* A damaged or unavailable local store must not block the classroom. */ }
let storageFailed=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;}catch{storageFailed=true;toast('El navegador no permite guardar. Descarga una copia de tu trabajo antes de salir.');}updateProfile();}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function updateProfile(){$('#profile-label').textContent=state.name||'Mi perfil';$('#avatar').textContent=(state.name||'T').slice(0,1).toUpperCase();}
const work=id=>state.work[id]||(state.work[id]={answers:{},attempts:0,hints:0,result:null,date:''});
const completed=()=>missions.filter(m=>state.work[m.id]?.result?.passed);
const points=()=>completed().reduce((a,m)=>a+m.points,0);
const progress=()=>Math.round(completed().length/8*100);
const nextMission=()=>missions.find(m=>!state.work[m.id]?.result?.passed)||missions[7];
const tags=m=>`<span class="tag ${m.level==='Intermedio'?'orange':m.level==='Avanzado'?'blue':''}">${m.level}</span><span>${m.department}</span>`;
function card(m){const done=state.work[m.id]?.result?.passed;return `<a class="mission-card" href="#mision/${m.id}"><span class="mission-icon" aria-hidden="true">${m.icon}</span><div class="mission-content"><div class="mission-meta"><span>MISIÓN ${m.num}</span><span class="tag ${done?'done':''}">${done?'✓ Revisada':state.work[m.id]?.attempts?'En práctica':'Por descubrir'}</span></div><h3>${m.title}</h3><p>${m.summary}</p><div class="mission-meta">${tags(m)}<span>◷ ${m.minutes} min</span><span>+${m.points} puntos</span></div></div><span class="arrow-link" aria-hidden="true">↗</span></a>`;}
const art=`<svg viewBox="0 0 470 260" fill="none" xmlns="http://www.w3.org/2000/svg" aria-label="Ilustración de una oficina con ordenador, plantas y documentos" role="img"><circle cx="280" cy="135" r="115" fill="#d3e2cc"/><path d="M80 220h350" stroke="#9ab298" stroke-width="2"/><rect x="90" y="182" width="320" height="13" rx="6" fill="#ad9474"/><path d="M107 195v54m284-54v54" stroke="#8e785b" stroke-width="9"/><rect x="150" y="62" width="194" height="120" rx="9" fill="#3f6551"/><rect x="158" y="70" width="178" height="101" rx="4" fill="#f9faf0"/><path d="M232 182v14m-24 0h50" stroke="#52735c" stroke-width="7"/><rect x="171" y="84" width="41" height="73" rx="3" fill="#e4eddd"/><path d="M179 96h23m-23 11h17m-17 11h20m-20 11h14" stroke="#9ebd9a" stroke-width="3" stroke-linecap="round"/><rect x="223" y="84" width="99" height="20" rx="3" fill="#e9d5b0"/><rect x="223" y="113" width="45" height="44" rx="3" fill="#eef2e4"/><path d="M230 147l9-12 8 4 12-17" stroke="#7ba680" stroke-width="3"/><rect x="279" y="113" width="43" height="44" rx="3" fill="#f3ede0"/><path d="M289 126h23m-23 9h18m-18 9h21" stroke="#b5ad91" stroke-width="3" stroke-linecap="round"/><rect x="102" y="135" width="27" height="46" rx="4" fill="#d2ae81"/><path d="M115 138v-33m0 21c-22-2-25-24-18-27 13-2 17 13 18 23m1-7c21-1 26-21 17-22-13-1-17 16-17 22" fill="#6e946c"/><rect x="354" y="160" width="27" height="24" rx="3" fill="#faf5e3"/><path d="M381 164h5c10 0 10 13 0 13h-5" stroke="#d3c5a3" stroke-width="3"/><path d="M357 149c-4-8 5-9 1-17m12 17c-4-8 5-9 1-17" stroke="#a4b29a" stroke-width="2" stroke-linecap="round"/><path d="M120 194h78l-11 9h-76z" fill="#ede9d5"/><rect x="245" y="208" width="80" height="7" rx="3" fill="#bdc7ac"/><circle cx="377" cy="58" r="20" fill="#f7f1d9"/><path d="m369 58 6 6 11-14" stroke="#78916b" stroke-width="3" stroke-linecap="round"/></svg>`;
function stats(){return `<div class="stats"><div class="stat"><span class="stat-icon">◈</span><div><small>Misiones completadas</small><strong>${completed().length}<span class="muted" style="font-size:13px"> / 8</span></strong></div></div><div class="stat"><span class="stat-icon">✧</span><div><small>Puntos de aprendizaje</small><strong>${points()}</strong></div></div><div class="stat"><span class="stat-icon">↗</span><div><small>Tu recorrido</small><strong>${progress()}<span style="font-size:13px"> %</span></strong></div></div><div class="stat"><span class="stat-icon">◎</span><div><small>Departamentos</small><strong>5<span style="font-size:12px;font-weight:400"> por explorar</span></strong></div></div></div>`;}
function home(){const m=nextMission();return `<div class="heading-row"><div><div class="eyebrow">TU ESPACIO DE APRENDIZAJE</div><h1>${state.name?'Hola, '+esc(state.name)+'.':'Bienvenido a tu nueva oficina.'}</h1><p class="subtitle">Aquí se aprende haciendo. Un encargo, un reto y un paso más.</p></div><div class="date-label">◷ A tu ritmo · Sin fechas límite</div></div><section class="hero"><div class="hero-text"><div class="eyebrow">ALJARAFE CONECTA · SIMULADOR DE EMPRESA</div><h2>Tu próximo trabajo<br>empieza practicando.</h2><p>Atiende clientes, resuelve incidencias y toma decisiones en una oficina. Tienes un equipo y pistas para acompañarte.</p><a class="btn" href="#mision/${m.id}">${completed().length?'Continuar mi recorrido':'Empezar mi primer día'} <span>→</span></a></div><div class="hero-art">${art}</div></section>${stats()}<div class="dashboard-grid"><section><div class="section-top"><h2>Tu mesa de trabajo</h2><a class="text-link" href="#misiones">Ver las 8 misiones →</a></div>${missions.filter(x=>!state.work[x.id]?.result?.passed).slice(0,3).map(card).join('')||`<div class="panel"><h2>¡Recorrido completado!</h2><p>Has revisado todas las misiones. Tu docente puede valorar ahora la calidad de tus textos y decisiones.</p><a class="btn" href="#progreso">Ver mi informe →</a></div>`}</section><aside><section class="panel mentor"><div class="person"><span class="person-avatar">C</span><div><strong>Clara, tu coordinadora</strong><small>Te acompaño en este recorrido</small></div></div><h3>Una cosa cada vez.</h3><p>Lee el encargo, prueba tu solución y revísala. Las pistas están para ayudarte, sin penalización.</p><button class="text-link" data-action="help" style="border:0;background:none;padding:0">Cómo funciona →</button></section><section class="panel"><div class="spread"><h3>Tu ruta de aprendizaje</h3><span class="tag">${progress()} %</span></div><div class="progress-track" role="progressbar" aria-label="Recorrido completado" aria-valuenow="${progress()}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${progress()}%"></div></div><div class="progress-caption"><span>De la práctica a la confianza</span><span>${completed().length}/8</span></div><ul class="checklist"><li><span class="checkmark">✓</span>Instrucciones paso a paso</li><li><span class="checkmark">✓</span>Sin límite de intentos</li><li><span class="checkmark">✓</span>Con documentos descargables</li></ul></section></aside></div>`;}
function list(){return `<div class="heading-row"><div><div class="eyebrow">APRENDE TRABAJANDO</div><h1>Elige tu próxima misión.</h1><p class="subtitle">Te recomendamos seguir el orden. También puedes practicar una actividad concreta.</p></div></div><div class="filters"><label class="sr-only" for="search">Buscar misiones</label><input id="search" type="search" placeholder="Buscar una misión…"><label class="sr-only" for="department">Departamento</label><select id="department"><option value="">Todos los departamentos</option>${[...new Set(missions.map(m=>m.department))].map(d=>`<option>${d}</option>`).join('')}</select><label class="sr-only" for="level">Nivel</label><select id="level"><option value="">Todos los niveles</option><option>Inicial</option><option>Intermedio</option><option>Avanzado</option></select></div><div class="mission-grid" id="mission-list">${missions.map(card).join('')}</div>`;}
function input(name,label,a,placeholder='',type='text'){return `<label class="field">${label}<input name="${name}" type="${type}" ${type==='text'&&['base','tax','total','diff','cost','net','rows','units'].includes(name)?'inputmode="decimal"':''} value="${esc(a[name]||'')}" placeholder="${esc(placeholder)}" maxlength="500" autocomplete="off" required></label>`;}
function area(name,label,a,placeholder='',rows=8){return `<label class="field">${label}<textarea name="${name}" placeholder="${esc(placeholder)}" rows="${rows}" maxlength="20000" required>${esc(a[name]||'')}</textarea></label>`;}
function choices(name,label,options,a){return `<fieldset><legend>${label}</legend>${options.map(([val,t])=>`<label class="choice"><input type="radio" name="${name}" value="${val}" ${a[name]===val?'checked':''} required><span>${t}</span></label>`).join('')}</fieldset>`;}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function task(m,a){switch(m.kind){
case'welcome':return `<div class="notice"><strong>${company.name}</strong><br>${company.activity}<br>${company.location}<br>${company.hours}</div><p class="subtitle">Tu equipo: Clara coordina la oficina; Diego gestiona compras; tú apoyas la administración y la atención al cliente.</p>${choices('priority','¿Qué haces antes de responder a la reclamación?',[['responder','Prometer una devolución sin revisar el pedido.'],['revisar','Revisar el pedido y la factura para conocer lo ocurrido.'],['borrar','Borrar la factura que parece incorrecta.']],a)}${choices('archive','¿Qué nombre facilita encontrar el documento?',[['generico','documento_final_bueno2'],['claro','2026-10_Academia-Horizonte_F-026'],['vacio','Sin título']],a)}`;
case'client':return `<div class="fields">${input('name','Nombre de la persona',a,'Nombre y apellidos')}${input('business','Negocio',a,'Nombre del negocio')}${input('city','Municipio',a,'Localidad')}${input('email','Correo electrónico',a,'nombre@negocio.example','email')}</div>${area('notes','Nota de la llamada',a,'¿Qué necesita? ¿Cuánto? ¿Para cuándo?',4)}`;
case'invoice':return `${table(['Concepto','Cantidad','Precio unitario'],[['Papel A4',10,'5,50 €'],['Carpetas',20,'2,80 €'],['Tóner',2,'45,00 €']])}<div class="notice warning">Total original de la factura: <strong>256,52 €</strong>. Tipo de IVA del supuesto: <strong>21 %</strong>.</div><button type="button" class="btn secondary" data-download="pedido">↓ Descargar pedido para Excel</button><div class="fields" style="margin-top:20px">${input('base','Base imponible (€)',a,'0,00')}${input('tax','Importe del IVA (€)',a,'0,00')}${input('total','Total correcto (€)',a,'0,00')}${input('diff','Importe cobrado de más (€)',a,'0,00')}</div>`;
case'email':return `<div class="notice">Para: lucia@horizonte.example · Este es un borrador de práctica. Se guardará aquí y no se enviará.</div>${input('subject','Asunto',a,'Revisión de la factura…')}${area('body','Tu respuesta a Lucía',a,'Saludo → reconocimiento → explicación → propuesta → despedida',11)}<span class="hint-text">La revisión detecta algunos elementos del texto. Tu docente valorará su calidad, tono y coherencia.</span><button type="button" class="btn secondary" data-download="borrador">↓ Descargar mi borrador</button>`;
case'purchase':return `${table(['Proveedor','Precio/caja sin IVA','Transporte sin IVA','Entrega'],[['Norte','17,50 €','0 €','2 días'],['Sur','16,00 €','12 €','5 días'],['Centro','19,00 €','0 €','1 día']])}<div class="notice">20 cajas · Presupuesto máximo: 450 € con IVA · Entrega: como máximo 3 días · IVA: 21 % también sobre el transporte.</div>${choices('supplier','¿Qué proveedor eliges?',[['norte','Norte'],['sur','Sur'],['centro','Centro']],a)}${input('cost','Coste final de tu elección (€)',a,'IVA y transporte incluidos')}${area('reason','Justifica tu decisión',a,'Compara el presupuesto disponible y la fecha de entrega.',5)}`;
case'data':return `${table(['ID','Cliente','Ciudad','Fecha','Producto','Cantidad','Precio (€)'],sales)}<div class="notice warning">Evidencia del albarán: V04 pertenece a <strong>Estudio Sur</strong>. La cantidad «dos» significa 2. La repetición completa de V02 es un duplicado.</div><button type="button" class="btn secondary" data-download="ventas">↓ Descargar ventas originales para Excel</button><div class="fields" style="margin-top:20px">${input('rows','Ventas únicas después de limpiar',a,'Número de registros')}${input('net','Venta neta total, sin IVA (€)',a,'0,00')}${input('units','Unidades vendidas en total',a,'Suma de cantidades')}</div>`;
case'schedule':return `${table(['Hora del martes','Agenda de Clara'],[['09:00–10:00','Gestión interna'],['10:00–10:30','Reunión de equipo'],['10:30–11:15','Disponible'],['11:15–12:00','Llamada con proveedor'],['12:00–14:00','Disponible']])}${choices('slot','¿A qué hora puede empezar la reunión de 45 minutos?',[['10:00','10:00'],['10:30','10:30'],['11:00','11:00'],['12:00','12:00']],a)}${area('body','Borrador de confirmación',a,'Incluye la persona, el día y las horas de inicio y finalización.',5)}`;
case'report':return `<div class="notice">Estructura propuesta: 1. Incidencia de facturación. 2. Propuesta de compra. 3. Resumen de ventas. 4. Acciones pendientes.</div>${area('body','Informe de cierre de jornada',a,'Resume lo que has comprobado y las acciones que propones. No des por realizadas devoluciones o compras.',16)}<button type="button" class="btn secondary" data-download="borrador">↓ Descargar mi informe</button><span class="hint-text">Evaluación orientativa del contenido. Requiere revisión docente de la redacción y la justificación.</span>`;
}}
function feedback(m){const w=work(m.id),r=w.result;if(!r)return '';return `<section class="feedback" role="status"><h3>${r.passed?'✓ Has incluido los elementos esperados.':'Vamos a revisar tu propuesta.'}</h3><p style="font-size:12px">Comprobaciones superadas: ${r.checks.filter(c=>c[1]).length} de ${r.checks.length} · ${r.score} %</p><ul>${r.checks.map(([t,ok])=>`<li class="${ok?'success':'fail'}">${ok?'✓':'↻'} ${esc(t)}</li>`).join('')}</ul><p class="hint-text">${r.indicative?'Esta comprobación es orientativa y no interpreta todo el significado de tu texto. La valoración final corresponde al docente.':'Puedes corregir y volver a revisar sin penalización.'}</p>${r.passed?`<a class="btn soft" href="${missions[Number(m.num)]?'#mision/'+missions[Number(m.num)].id:'#progreso'}">${Number(m.num)<8?'Ir a la siguiente misión':'Ver mi informe de aprendizaje'} →</a>`:''}</section>`;}
function mission(id){const m=missions.find(x=>x.id===id);if(!m)return `<div class="panel"><h1>Misión no encontrada</h1><a href="#misiones">Volver a las misiones</a></div>`;const w=work(id);return `<a class="breadcrumbs" href="#misiones">← Volver a las misiones</a><div class="mission-heading"><div class="mission-meta"><span class="eyebrow">MISIÓN ${m.num} / 08</span>${tags(m)}<span>${m.minutes} min orientativos</span></div><h1>${m.title}</h1><p class="subtitle">${m.objective}</p></div><div class="content-grid"><section><div class="mail"><strong>✉ ${m.sender}</strong><p>${m.message}</p></div><div class="task-area"><h2>Ahora te toca a ti.</h2><form id="task-form" data-mission="${id}">${task(m,w.answers)}<div class="task-actions"><button class="btn" type="submit">Revisar mi propuesta →</button><button class="btn secondary" type="button" data-action="save-draft">Guardar borrador</button><span class="saved" id="save-status">${w.date?'Borrador recuperado':'Se guarda mientras escribes'}</span></div></form><div id="feedback">${feedback(m)}</div></div></section><aside><section class="panel"><div class="eyebrow">TU HOJA DE RUTA</div><h3 style="margin-top:10px">Paso a paso</h3><ol class="steps">${m.steps.map(s=>`<li>${s}</li>`).join('')}</ol></section><section class="panel mentor"><h3>¿Te has atascado?</h3><p>Prueba una pista. Pedir ayuda forma parte del aprendizaje.</p><button class="btn secondary" data-action="hint" ${w.hints>=2?'disabled':''}>${w.hints>=2?'Ya tienes las dos pistas':'Mostrar pista '+(w.hints+1)}</button><div id="hints">${m.hints.slice(0,w.hints).map(h=>`<div class="hint-box">${h}</div>`).join('')}</div></section><section class="panel"><h3>Practica con IA</h3><p>Copia el encargo para conversar con un tutor en ChatGPT. Este simulador usa actividades y pistas preparadas; no tiene un modelo de IA conectado.</p><button class="btn soft" data-action="ai">Preparar práctica con IA ↗</button></section></aside></div>`;}
function directory(){let list=[...clients];if(state.work.clientes?.result?.passed)list.push({id:'C-004',name:'Sara Medina',business:'Taller Creativo',city:'San Juan de Aznalfarache',email:'sara@tallercreativo.example',need:'12 carpetas. Presupuesto antes del viernes.',status:'Solicitud registrada'});return `<div class="heading-row"><div><div class="eyebrow">ATENCIÓN AL CLIENTE</div><h1>Personas detrás de cada encargo.</h1><p class="subtitle">Tu directorio de práctica. Todos los contactos son ficticios.</p></div></div><div class="toolbar"><a class="btn" href="#mision/clientes">+ Practicar el alta de una clienta</a><button class="btn secondary" data-download="clientes">↓ Descargar directorio para Excel</button></div><div class="client-grid">${list.map(c=>`<article class="client-card"><div class="spread"><span class="client-initials">${esc(c.name.split(' ').map(s=>s[0]).join(''))}</span><span class="tag">${c.id}</span></div><h3>${esc(c.name)}</h3><p><strong>${esc(c.business)}</strong><br>${esc(c.city)}</p><p class="email">${esc(c.email)}</p><div class="notice">${esc(c.need)}</div><span class="tag">${esc(c.status)}</span></article>`).join('')}</div>`;}
function documents(){const docs=[['pedido','Pedido de Academia Horizonte','Tres líneas de productos para comprobar la factura en Excel.','CSV · Compatible con Excel'],['ventas','Ventas pendientes de limpieza','Datos con errores preparados para la misión 06.','CSV · Separador punto y coma'],['clientes','Directorio de clientes','Los contactos ficticios de esta empresa de prácticas.','CSV · Compatible con Excel'],['plantilla','Plantilla del informe de cierre','Una estructura editable para organizar tus conclusiones.','TXT · Word o cualquier editor']];return `<div class="heading-row"><div><div class="eyebrow">EL ARCHIVO DE TU OFICINA</div><h1>Documentos para trabajar.</h1><p class="subtitle">Descarga, practica en tu ordenador y vuelve para comprobar los resultados.</p></div></div><div class="notice">Para abrir un CSV en Excel: Datos → Desde texto/CSV → selecciona UTF-8 y el separador «punto y coma». Si tu versión lo reconoce, basta con abrir el archivo.</div><div class="doc-grid">${docs.map(([id,title,desc,format])=>`<article class="panel"><div class="doc-icon">▤</div><span class="eyebrow">${format}</span><h2 style="margin-top:10px">${title}</h2><p>${desc}</p><button class="btn secondary" data-download="${id}">↓ Descargar documento</button></article>`).join('')}</div>`;}
function progressPage(){return `<div class="heading-row"><div><div class="eyebrow">EVIDENCIAS DE APRENDIZAJE</div><h1>Cada paso cuenta.</h1><p class="subtitle">${esc(state.name||'Tu perfil de práctica')} · Resultado orientativo, pendiente de valoración docente.</p></div></div>${stats()}<div class="toolbar"><button class="btn" data-action="print">Imprimir / Guardar PDF</button><button class="btn secondary" data-download="informe">↓ Descargar informe completo</button><button class="btn secondary" data-action="backup">↓ Guardar copia de mi trabajo</button><button class="btn secondary" data-action="restore">Recuperar una copia</button></div><div class="notice">La copia permite continuar en otro dispositivo al importarla. El PDF se obtiene desde la ventana de impresión. Este informe es una evidencia de práctica, no una acreditación oficial.</div><section class="panel"><h2>Mi recorrido</h2>${missions.map(m=>{const w=state.work[m.id];return `<div class="report-row"><div><strong>${m.num}. ${m.title}</strong><small>${w?.attempts||0} revisiones · ${w?.hints||0} pistas consultadas</small></div><span class="tag ${w?.result?.passed?'done':''}">${w?.result?w.result.score+' %':w?.answers&&Object.values(w.answers).some(Boolean)?'Borrador':'Sin empezar'}</span></div>`;}).join('')}</section>${missions.filter(m=>state.work[m.id]&&Object.values(state.work[m.id].answers).some(Boolean)).map(m=>`<section class="panel"><h3>${m.num}. ${m.title}</h3><div class="report-text">${esc(answerText(state.work[m.id].answers))}</div></section>`).join('')}<section class="panel no-print"><h3>Gestionar mi trabajo</h3><p>Usa un alias para identificar tu práctica. Si compartes ordenador, descarga tu copia antes de comenzar un recorrido nuevo.</p><div class="toolbar"><button class="btn secondary" data-action="profile">Cambiar mi alias</button><button class="btn danger" data-action="reset">Empezar un recorrido nuevo</button></div></section>`;}
function teacher(){return `<div class="heading-row"><div><div class="eyebrow">GUÍA DE FACILITACIÓN · RUBÉN MUÑOZ DOCENTE</div><h1>Una oficina. Muchas formas de aprender.</h1><p class="subtitle">Material de apoyo para dinamizar, acompañar y evaluar la experiencia.</p></div></div><div class="notice warning">Esta guía y las soluciones son públicas. Esta vista no es un acceso protegido ni un panel de seguimiento de otros alumnos.</div><div class="toolbar"><button class="btn secondary" data-action="print">Imprimir guía</button><button class="btn soft" data-download="guia">↓ Descargar guía docente</button></div><div class="guide-grid"><section class="panel"><h2>Cómo llevarla al aula</h2><ol><li>Presenta la empresa y explica que todos sus datos son ficticios.</li><li>Propón trabajo individual o parejas con roles rotativos.</li><li>Haz primero una demostración breve de la misión 01.</li><li>Alterna la práctica en pantalla con Word y Excel.</li><li>Recoge el informe descargable por el canal del centro.</li><li>Debate decisiones y revisa la calidad de textos y cálculos.</li></ol><p>Duración estimada: 230 minutos de misiones, más explicación y puesta en común. Propuesta: 6 horas de aula en tres sesiones de 2 horas. No constituye por sí sola un curso acreditado.</p></section><section class="panel"><h2>Adaptaciones y apoyos</h2><ul class="steps"><li>Inicial: acompaña la lectura y ofrece un ejemplo antes de practicar.</li><li>Intermedio: pide justificar cada decisión.</li><li>Avanzado: añade gráficos de ventas y una presentación de resultados.</li><li>Accesibilidad: instrucciones escritas, etiquetas de formulario, uso con teclado y diseño adaptable.</li><li>Las pistas y los intentos no reducen los puntos: se premia completar la práctica.</li></ul></section></div><section class="panel"><h2>Rúbrica propuesta</h2>${table(['Criterio','Peso','Evidencia'],[['Exactitud de los datos','40 %','Cálculos y datos del caso'],['Claridad y trato','25 %','Correo y confirmación'],['Justificación','20 %','Selección de proveedor e informe'],['Revisión y presentación','15 %','Organización y corrección de documentos']])}<p>Las comprobaciones automáticas de textos buscan algunos elementos; pueden aceptar una respuesta inadecuada o pedir cambios a una respuesta válida. Revisa tú el significado y la coherencia antes de calificar.</p></section><section class="panel"><h2>Soluciones y pautas de revisión</h2>${missions.map(m=>`<details class="teacher-section"><summary>${m.num}. ${m.title}</summary><p>${guides[m.kind]}</p></details>`).join('')}</section><section class="panel"><h2>Qué guarda esta versión</h2><p>Alias, respuestas, intentos, pistas y resultados en el almacenamiento local del navegador. No hay cuentas, base de datos compartida ni envío de información a un servidor. Cada navegador tiene su propio recorrido; las copias se intercambian manualmente. Los clientes y trabajadores son personajes ficticios.</p><h3>Uso de IA</h3><p>El botón «Practica con IA» prepara un encargo para un servicio externo. El alumno decide si lo copia y lo utiliza. No se transmite automáticamente su trabajo ni hay claves de API en la web. Los diálogos internos son casos y pistas preparados.</p></section>`;}
const labels={name:'Persona',business:'Negocio',city:'Municipio',email:'Correo',notes:'Nota de la llamada',base:'Base imponible',tax:'IVA',total:'Total correcto',diff:'Diferencia',subject:'Asunto',body:'Texto',supplier:'Proveedor',cost:'Coste final',reason:'Justificación',rows:'Ventas únicas',net:'Venta neta',units:'Unidades',slot:'Hora de inicio',priority:'Prioridad',archive:'Archivo'};
function answerText(a){return Object.entries(a).map(([k,v])=>`${labels[k]||k}: ${v}`).join('\n\n');}
function route(){const hash=location.hash.slice(1)||'inicio';const [page,id]=hash.split('/');const nav=[['inicio','◈','Mi oficina'],['misiones','▤','Misiones'],['clientes','◎','Clientes'],['documentos','▱','Documentos'],['progreso','↗','Mi progreso'],['docente','▦','Guía docente']];$('#nav').innerHTML=nav.map(([key,icon,title],i)=>`${i===4?'<div class="nav-divider"></div>':''}<a href="#${key}" class="${page===key||(page==='mision'&&key==='misiones')?'active':''}" ${page===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${title}${key==='misiones'?'<span class="count">8</span>':''}</a>`).join('');$('#section-label').textContent=page==='mision'?'Misión '+(missions.find(m=>m.id===id)?.num||''):nav.find(n=>n[0]===page)?.[2]||'Mi oficina';$('#main').innerHTML=({inicio:home,misiones:list,clientes:directory,documentos:documents,progreso:progressPage,docente:teacher}[page]||(()=>mission(id)))();updateProfile();bindPage();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
function currentMission(){return missions.find(m=>m.id===(location.hash.split('/')[1]));}
function capture(){const f=$('#task-form');if(!f)return;const w=work(f.dataset.mission);const answers=Object.fromEntries(new FormData(f));const changed=JSON.stringify(w.answers)!==JSON.stringify(answers);w.answers=answers;w.date=new Date().toISOString();if(changed)w.result=null;save();const el=$('#save-status');if(el)el.textContent=storageFailed?'Descarga una copia para conservar tu trabajo.':'Borrador guardado';if(changed)$('#feedback').innerHTML='';}
function bindPage(){const form=$('#task-form');if(form){form.addEventListener('input',capture);form.addEventListener('change',capture);form.addEventListener('submit',e=>{e.preventDefault();const id=form.dataset.mission,w=work(id),m=missions.find(x=>x.id===id);w.answers=Object.fromEntries(new FormData(form));w.attempts++;w.result=evaluate(m.kind,w.answers);w.date=new Date().toISOString();save();$('#feedback').innerHTML=feedback(m);$('#feedback').scrollIntoView({behavior:'smooth',block:'nearest'});});}if($('#search')){const filter=()=>{const search=$('#search').value.toLocaleLowerCase('es');const found=missions.filter(m=>(m.title+' '+m.summary).toLocaleLowerCase('es').includes(search)&&(!$('#department').value||m.department===$('#department').value)&&(!$('#level').value||m.level===$('#level').value));$('#mission-list').innerHTML=found.map(card).join('')||'<div class="empty">No hay misiones con esos filtros. Prueba otra búsqueda.</div>';};['#search','#department','#level'].forEach(s=>$(s).addEventListener('input',filter));}}
function showDialog(html){$('#dialog-body').innerHTML=html;$('#dialog').showModal();}
function help(){showDialog(`<div class="eyebrow">BIENVENIDO A ALJARAFE CONECTA</div><h2>Tu primera jornada, paso a paso.</h2><ol class="steps"><li>Elige «Empezar mi primer día» o entra en Misiones.</li><li>Lee el mensaje de tu compañero o cliente ficticio.</li><li>Sigue los pasos y completa la práctica.</li><li>Pulsa «Revisar mi propuesta» para comprobarla.</li><li>Si lo necesitas, consulta las pistas y vuelve a intentarlo.</li><li>En «Mi progreso» puedes descargar tu trabajo.</li></ol><p>No necesitas registrarte. Usa un alias y guarda una copia si vas a cambiar de dispositivo. El progreso es local a este navegador.</p><p>Las misiones no envían correos, realizan compras ni reservan citas reales.</p><a class="btn" href="#mision/bienvenida" data-action="close">Empezar la primera misión →</a>`);}
function profile(){showDialog(`<h2>¿Cómo quieres que te llamemos?</h2><p>Usa un alias. No necesitamos tu nombre completo ni datos personales.</p><form id="profile-form"><label class="field">Tu alias<input name="alias" maxlength="60" value="${esc(state.name)}" placeholder="Por ejemplo: Equipo Verde" required></label><button class="btn" type="submit">Guardar mi alias</button></form>`);$('#profile-form').onsubmit=e=>{e.preventDefault();state.name=new FormData(e.target).get('alias').trim().slice(0,60);save();$('#dialog').close();route();};}
function download(name,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(';')).join('\r\n');}
function fullReport(){return `ALJARAFE CONECTA · INFORME DE PRÁCTICA\nAutor del diseño: Rubén Muñoz Valadés\nAlias: ${state.name||'Sin alias'}\nFecha: ${new Date().toLocaleDateString('es-ES')}\nRecorrido: ${completed().length}/8 · Puntos: ${points()}\nResultado orientativo; requiere revisión docente.\n\n`+missions.map(m=>{const w=state.work[m.id];return `${m.num}. ${m.title}\nEstado: ${w?.result?w.result.score+' % de comprobaciones superadas':'Sin revisar'}\nIntentos: ${w?.attempts||0} · Pistas: ${w?.hints||0}\n${w?answerText(w.answers):'Sin respuestas'}\n${w?.result?w.result.checks.map(([t,ok])=>`${ok?'✓':'Pendiente:'} ${t}`).join('\n'):''}\n`;}).join('\n------------------------------\n\n');}
function documentDownload(id){if(id==='pedido')download('Pedido_Academia_Horizonte.csv',csv([['Producto','Cantidad','Precio unitario sin IVA'],['Papel A4',10,'5,50'],['Carpetas',20,'2,80'],['Tóner',2,'45,00']]),'text/csv;charset=utf-8');if(id==='ventas')download('Ventas_originales_Aljarafe.csv',csv([['ID','Cliente','Ciudad','Fecha','Producto','Cantidad','Precio unitario'],...sales]),'text/csv;charset=utf-8');if(id==='clientes'){const rows=clients.map(c=>[c.id,c.name,c.business,c.city,c.email,c.need]);if(state.work.clientes?.result?.passed)rows.push(['C-004','Sara Medina','Taller Creativo','San Juan de Aznalfarache','sara@tallercreativo.example','12 carpetas antes del viernes']);download('Directorio_clientes_ficticios.csv',csv([['ID','Persona','Negocio','Municipio','Correo','Necesidad'],...rows]),'text/csv;charset=utf-8');}if(id==='plantilla')download('Plantilla_informe_cierre.txt','ALJARAFE CONECTA · INFORME DE CIERRE\nAlias:\nFecha:\n\n1. INCIDENCIA F-026\nDatos comprobados:\nSolución propuesta:\n\n2. PROPUESTA DE COMPRA\nProveedor y coste:\nJustificación:\n\n3. RESUMEN DE VENTAS\nRegistros y venta neta:\n\n4. ACCIONES PENDIENTES\nAcción, responsable y siguiente paso:\n');if(id==='informe')download('Informe_practica_Aljarafe_Conecta.txt',fullReport());if(id==='borrador'){const m=currentMission(),w=work(m.id);download(`Mision_${m.num}_borrador.txt`,`${m.title}\nAlias: ${state.name||'Sin alias'}\n\n${answerText(w.answers)}`);}if(id==='guia')download('Guia_docente_Aljarafe_Conecta.txt','ALJARAFE CONECTA · GUÍA DOCENTE\nRubén Muñoz Valadés · Docente FPE\n\nObjetivo: practicar ofimática, administración y atención al cliente mediante casos conectados.\nDuración orientativa: 6 horas de aula, incluidas explicaciones y puesta en común.\nMetodología: demostración, práctica individual o parejas, corrección y reflexión.\nRúbrica: exactitud 40 %, claridad 25 %, justificación 20 %, revisión y presentación 15 %.\nEvaluación: las comprobaciones de texto son orientativas; revisar significado y coherencia.\nEsta guía es pública. No hay cuentas ni seguimiento centralizado.\n\n'+missions.map(m=>`${m.num}. ${m.title}\nObjetivo: ${m.objective}\n${m.minutes} min · ${m.department}\nSolución y pauta: ${guides[m.kind]}`).join('\n\n'));}
function aiPractice(){const m=currentMission();const prompt=`Actúa como tutor de práctica de formación para el empleo. Estoy trabajando en la empresa ficticia Aljarafe Conecta, dedicada a suministros de oficina y servicios digitales. Mi nivel es principiante. Explícame en español de España, con pasos pequeños.\n\nMisión: ${m.title}\nObjetivo: ${m.objective}\nEncargo: ${m.message}\n\nAcompáñame haciendo una pregunta cada vez. Empieza pidiéndome identificar los datos y la tarea. No me des la solución completa de entrada. Cuando responda, ayúdame a comprobarla y explícame los errores. Usa solo datos ficticios y no inventes acciones realizadas. Para los cálculos, pídeme consultar la tabla de la misión si te falta algún dato. Si no puedes verificar algo, indícalo.`;showDialog(`<h2>Un tutor para esta misión</h2><p>1. Copia las instrucciones. 2. Abre ChatGPT. 3. Pégalas para empezar a practicar. Puedes necesitar una cuenta y el servicio puede tener límites propios.</p><label class="field">Instrucciones listas para copiar<textarea id="ai-prompt" readonly rows="10">${esc(prompt)}</textarea></label><div class="toolbar"><button class="btn" id="copy-prompt">Copiar instrucciones</button><a class="btn secondary" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">Abrir ChatGPT ↗</a><button class="btn soft" id="download-prompt">↓ Descargar instrucciones</button></div><p>No se envía automáticamente ninguna respuesta del simulador.</p>`);$('#copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText(prompt);toast('Instrucciones copiadas. Pégalas en ChatGPT.');}catch{$('#ai-prompt').select();toast('Selecciona y copia el texto de las instrucciones.');}};$('#download-prompt').onclick=()=>download('Practica_IA_'+m.id+'.txt',prompt);}
document.addEventListener('click',e=>{const d=e.target.closest('[data-download]');if(d){documentDownload(d.dataset.download);return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='help')help();if(action==='profile')profile();if(action==='close')$('#dialog').close();if(action==='save-draft'){capture();toast(storageFailed?'Descarga una copia para conservar tu trabajo.':'Borrador guardado en este navegador.');}if(action==='hint'){const m=currentMission(),w=work(m.id);w.hints=Math.min(2,w.hints+1);save();$('#hints').innerHTML=m.hints.slice(0,w.hints).map(h=>`<div class="hint-box">${h}</div>`).join('');b.textContent=w.hints>=2?'Ya tienes las dos pistas':'Mostrar pista 2';b.disabled=w.hints>=2;}if(action==='ai')aiPractice();if(action==='print')window.print();if(action==='backup')download('Copia_mi_trabajo_Aljarafe_Conecta.json',JSON.stringify(state,null,2),'application/json');if(action==='restore')$('#restore-file').click();if(action==='reset'){showDialog('<h2>¿Empezar un recorrido nuevo?</h2><p>Se borrarán el alias y las respuestas de este navegador. Descarga primero una copia si quieres conservar tu trabajo.</p><div class="toolbar"><button class="btn secondary" data-action="backup">Descargar copia antes de borrar</button><button id="confirm-reset" class="btn danger">Borrar y empezar de nuevo</button></div>');$('#confirm-reset').onclick=()=>{state={app:'aljarafe-conecta',version:1,name:'',work:{}};save();$('#dialog').close();location.hash='inicio';route();toast('Recorrido nuevo preparado.');};}});
$('#restore-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('El archivo supera el tamaño permitido de 1 MB.');const imported=validateBackup(JSON.parse(await file.text()));showDialog(`<h2>Recuperar una copia</h2><p>Se sustituirá el recorrido de este navegador por la copia de <strong>${esc(imported.name||'Sin alias')}</strong>. Guarda primero tu trabajo actual si lo necesitas.</p><div class="toolbar"><button class="btn secondary" data-action="backup">Guardar copia actual</button><button id="confirm-import" class="btn">Recuperar esta copia</button></div>`);$('#confirm-import').onclick=()=>{state=imported;save();$('#dialog').close();route();toast('Copia recuperada. Puedes continuar.');};}catch(err){toast('No se ha recuperado la copia: '+(err.message||'archivo no válido'));}e.target.value='';});
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();};
$('#close-dialog').onclick=()=>$('#dialog').close();$('#help-btn').onclick=help;$('#profile-btn').onclick=profile;
window.addEventListener('hashchange',route);route();
